def solve(df: pl.DataFrame) -> pl.DataFrame:
    df = df.with_columns(groups=pl.Series(["a", "a", "a", "b", "b", "a", "a"]))
    return (
        df.group_by_dynamic(
            "time",
            every="1h",
            closed="both",
            group_by="groups",
            include_boundaries=True,
        ).agg(pl.col("n"))
    )

